def cdf(x):return (1+mp.erf(mp.mpf(str(x))/mp.sqrt(2)))/2
count=0
for c in CASES:
 if c['kind']=='normal':
  mu=mp.mpf(str(c['mu']));s=mp.mpf(str(c['sigma']))
  lower=c['lo'];upper=c['hi']
  val=(cdf((mp.mpf(str(upper))-mu)/s) if upper is not None else 1)-(cdf((mp.mpf(str(lower))-mu)/s) if lower is not None else 0)
 elif c['kind']=='quantile':
  mu=mp.mpf(str(c['mu']));s=mp.mpf(str(c['sigma']));F=mp.mpf(str(c['F']))
  val=mu+s*mp.sqrt(2)*mp.erfinv(2*F-1)
 else:
  n=c['n'];p=mp.mpf(str(c['p']))
  val=mp.fsum(mp.binomial(n,k)*p**k*(1-p)**(n-k) for k in range(c['lo'],c['hi']+1))
 assert abs(float(val)-c['value'])<1e-9*max(1,abs(c['value'])),c
 count+=1
# Exact source data and semantic corrections, including cases not covered by
# the helper-generated probability table. Check actual authored rows too.
def require(key,text):
 global count
 assert text in html.unescape(rows[key]['solutionHtml']),(key,text)
 count+=1
T=[14.6,8.8,7.2,7.3,10.1,11.9,12.2,12.1,15.2,11.1,10.6,12.7,8.9,10,9.5,9.3,10.9,10.7,11.9,9.5,10.4,9.7,9.8,13.1,12.6,15.9,14.9,13.5,14.2,16.8,16.2]
assert sum(x<11.6 for x in T)==16
assert sum(9<x<14.2 for x in T)==20
assert sum(6.5<x<16.8 for x in T)==30
count+=3
require('3.1/q9','20/31');require('3.1/q9','30/31')
require('3.3/q3','P(b<X<a)=0')
assert float(cdf((139.03847045059175-177)/33))<.126
require('3.4/q6',r'\Phi^{-1}(0.125)')
# Coverage for n=39 fails95%, n=40 succeeds; source key21 is insufficient.
coverage=lambda n:2*cdf(mp.sqrt(n)/mp.mpf('3.2'))-1
assert coverage(39)<.95<coverage(40)
require('exam/q3',r'n_{\min}=40');count+=1
# Die maximum prime: enumerate rather than reuse the algebraic count.
assert sum(max(i,j) in (2,3,5) for i in range(1,7) for j in range(1,7))==17
require('exam/q8',r'\frac{17}{36}');count+=1
# Continuity corrected tail threshold, compare neighbouring integer events.
s=mp.sqrt(mp.mpf('61.6'))
a=1-cdf((mp.mpf('149.5')-140)/s);b=1-cdf((mp.mpf('150.5')-140)/s)
assert a>.1>b and abs(b-.1)<abs(a-.1)
require('3.6/q5','q=151');count+=1
# Large-prize band excludes the grand-prize band shown in the source diagram.
z=lambda p:mp.sqrt(2)*mp.erfinv(2*mp.mpf(str(p))-1)
s=70/(z(.95)-z(.2));mu=80-s*z(.2)
large=300*(cdf((180-mu)/s)-cdf((150-mu)/s))
assert 13.9<float(large)<14.1
require('problem-a/qgold','150<X<180');count+=1
# Quantile equations with near cancellation retain full precision.
s=mp.mpf('1.45')/(z(.7)-2*z(.6));a=mp.mpf('1.45')+s*z(.6)
assert abs(float(1-cdf((2*a-mp.mpf('1.45'))/s))-.3)<1e-12
assert abs(float(cdf((a-mp.mpf('1.45'))/s))-.6)<1e-12
count+=2
print(f'{count} independent normal/binomial and source-condition checks passed')
